def _bucket_keys():
    """度数直方图的桶标签序列（与 _bucket 返回值一致，含 <3 兜底桶）。"""
    return ([f"<{_DEG_BUCKETS[0][0]}"]
            + [f"{lo}" if hi is None else f"{lo}-{hi - 1}"
               for (lo, hi) in _DEG_BUCKETS])

def holes_of(net):
    """洞 = 顶点不重复的 k>=4 边面。返回边长列表（降序）。"""
    hs = []
    for c in net.faces():
        vs = net.face_vertices(c)
        if len(vs) >= 4 and len(set(vs)) == len(vs):
            hs.append(len(vs))
    return sorted(hs, reverse=True)

def sigma_field(net):
    """全局 σ 读数：`σ_global = V/E`、局部 `σ_v`、直方图、`∇σ_v`。"""
    ids = net.ids()
    E = net.E()
    sg = {v: L1.sigma_of(net.deg(v)) for v in ids}
    vals = sorted(sg.values())
    n = len(vals)
    return {"V": len(ids), "E": E, "sigma_global": (len(ids) / E) if E else float("inf"),
            "sigma_min": vals[0] if vals else 0.0,
            "sigma_median": vals[n // 2] if vals else 0.0,
            "sigma_max": vals[-1] if vals else 0.0,
            "sigma": sg, "grad_sigma": L1.grad_sigma(net)}

def bare_step(net, dmin=3):
    """裸一帧：锥化全部真面 → 帧末修剪。返回 (S_{t+1}, 锥化数, 被删数)。

    读 S_t 的面迹快照，写副本 S_{t+1}；一帧只删一次，不级联。
    """
    nx = _clone(net)
    coned = 0
    for cyc in net.faces():
        vs = net.face_vertices(cyc)
        if len(vs) == 3 and len(set(vs)) == 3 and nx.cone_tri_face(*vs) is not None:
            coned += 1
    dead = [v for v in nx.ids() if nx.deg(v) < dmin]
    for v in dead:
        nx.remove_vertex(v)
    return nx, coned, len(dead)

def edge_list(net):
    """去重无向边表（网络骨架的边），确定性升序。纯 id，不需坐标。"""
    es = set()
    for v in net.ids():
        for w in net.rot[v]:
            es.add((v, w) if v < w else (w, v))
    return sorted(es)

def seed_patch(R=2):
    """三角晶格六边形贴片（R=2 → 19 元胞）的开放种子。

    环序 = 6 个晶格方向（逆时针）中实际存在邻居的子序列；子序列保持
    环序，故每个元胞的 rot 是一个合法环序。R=2 时 V=19 E=42，
    外边界为 12 边形 → 洞 1 个（开放）。
    """
    dirs = [(0, 1), (-1, 1), (-1, 0), (0, -1), (1, -1), (1, 0)]
    keys = []
    for q in range(-R, R + 1):
        for r in range(max(-R, -q - R), min(R, -q + R) + 1):
            keys.append((q, r))
    idx = {k: i for i, k in enumerate(keys)}
    rot = {}
    for k in keys:
        q, r = k
        rot[idx[k]] = [idx[(q + dq, r + dr)] for (dq, dr) in dirs
                       if (q + dq, r + dr) in idx]
    return rot

def attr_series(nets, ids=None):
    """持久 id 的属性时间序列：`deg / r(deg) / σ_v`（r、σ 取自 §6.3 局部量）。

    `ids=None` ⇒ 取**全帧存活**的 id（id 持久性最强的一批）；缺席帧记 `None`。
    """
    if ids is None:
        live = [set(n.ids()) for n in nets]
        ids = sorted(set.intersection(*live)) if live else []
    out = {}
    for v in ids:
        dg, rr, sg = [], [], []
        for net in nets:
            if v in net.rot:
                d = net.deg(v)
                dg.append(d)
                rr.append(L1.radius_of(d))
                sg.append(L1.sigma_of(d))
            else:
                dg.append(None)
                rr.append(None)
                sg.append(None)
        out[v] = {"deg": dg, "r": rr, "sigma": sg}
    return out

def hop_integral(r, sigma, sigma0):
    """跳数积分离散化 `ΔN(r_k) = Σ_{j>k}(σ_j − σ₀)·w_j` → {"r","dN"}。

    箱宽取**右端点**约定：`w_j = r_j − r_{j−1}`（`j ≥ 1`）、`w_0 = r_1 − r_0`；
    `m == 1` 退化时 `w_0 = 1.0`、`dN = [0.0]`（最外箱之外无内容）。
    """
    m = len(r)
    if m == 0:
        return {"r": [], "dN": []}
    # --- S1 箱宽（m==1 退化取 1.0）---
    w = [1.0] * m
    for j in range(1, m):
        w[j] = r[j] - r[j - 1]
    if m >= 2:
        w[0] = r[1] - r[0]
    # --- S2 尾部求和 ---
    dN = [0.0] * m
    for k in range(m):
        s = 0.0
        for j in range(k + 1, m):
            s += (sigma[j] - sigma0) * w[j]
        dN[k] = s
    return {"r": list(r), "dN": dN}

def anchors_of(net):
    """锚点 = σ 局部极值（坐标无关；与 §6.4 `anchors` 同口径）。

    `σ_v = 2/deg_v` ⇒ `∇σ_v < 0 ⟺ deg_v < mean_{w~v} deg_w`（局部最小度 = σ 局部极大）。
    等度图（如正二十面体）两者皆空 —— 此时不存在"引力中心"。
    """
    gs = L1.grad_sigma(net)
    return {"sinks": sorted(v for v, g in gs.items() if g < -_TOL),
            "sources": sorted(v for v, g in gs.items() if g > _TOL)}

def _seeds():
    """构造种子（**每次调用都新建**，绝不复用缓存对象）。

    注意：`RotNet(dict)` 只浅拷贝外层 dict，值（环序 list）是与入参共享的；
    而 `puncture()` / `remove_vertex` / `cone_*` 都会**原地改写**这些 list。
    若返回缓存对象，一次穿刺就会污染此后所有拿到的种子（实测：紧跟 punc=1 的
    配置会在 t=0 就报「0 is not in list」）。故此处逐行复制。
    """
    from combinatorial_proto import RotNet, SEEDS
    return {n: RotNet({v: list(r) for v, r in SEEDS[n]().items()})
            for n in ("tetra", "icosa")}

def global_evolution(core, nframes=6, k_delta=KAPPA, theta_delta=THETA_DELTA,
                     theta_mu=THETA_MU, k_closed=K_CLOSED):
    """L3 入口：跑 L0 取帧序列 → ① 对齐 ② 指标 ③ 闭合判据（不做任何坐标求解）。"""
    nets, events = trace_frames(core, nframes)
    tr = frame_trace(nets)
    rows = series(nets, events, k_delta)
    for r, t in zip(rows, tr):
        r["delta_dmin"] = delta(nets[r["t"]], core.dmin)
    cl = closure_series(rows, theta_delta, theta_mu, k_closed)
    return {"rows": rows, "closure": cl, "trace": tr,
            "attrs": attr_series(nets),
            "V": [t["V"] for t in tr], "E": [t["E"] for t in tr]}

def count_separating_triangles(net):
    """分离三角数 = 是 3-团、但两个定向都不是真面 的三角形个数。
    这些正是旧判据「j,k 互邻即缝隙」会误当缝隙去锥化的位置。"""
    n = 0
    for (i, j, k) in all_triangles(net):
        if not (net.tri_is_face(i, j, k) or net.tri_is_face(i, k, j)):
            n += 1
    return n

def redshift_proxy(net, root=None):
    """沿 BFS 最短路的 σ 相对变化累积（**代理读数，非物理预言**）。

    `z_v = Σ_{沿 v→root 的路径} (σ_cur − σ_next)/σ_next`。
    σ 高（关系密、温度低）区 => z 为正；等度图上 `σ ≡ const` ⇒ `z ≡ 0`。
    """
    ids = net.ids()
    if not ids:
        return {}
    sg = {v: L1.sigma_of(net.deg(v)) for v in ids}
    root = ids[0] if root is None else root
    z = {root: 0.0}
    q = deque([root])
    while q:
        i = q.popleft()
        for w in net.rot[i]:
            if w in z:
                continue
            z[w] = z[i] + (sg[w] - sg[i]) / sg[i]
            q.append(w)
    return z

def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）——「谁连着谁」的集合形式。"""
    return {(v, w) if v < w else (w, v)
            for v in net.ids() for w in net.rot[v]}

def run_frame(net, mode="all", dmin=2, unguarded=False):
    """一帧：创生(V+) → 判断悬挂 → 删除(V-)。一帧只做一次删除，无级联。

    创生候选在帧首快照（模拟 L1 请求队列），逐个以判据复核后执行。
    返回 (born_ids, dead_ids)。
    """
    f0 = net.faces()
    cand_tri = [net.face_vertices(c) for c in f0 if len(c) == 3]
    cand_hole = [net.face_vertices(c) for c in f0 if len(c) >= 4]

    born = []
    if unguarded:
        # 旧判据「j,k 互邻即缝隙」：3-团一律锥化。若它确是真面（两个定向
        # 之一），按正确定向锥化；否则（分离三角）无定向可用 → 野蛮插入。
        for (i, j, k) in all_triangles(net):
            if net.tri_is_face(i, j, k):
                w = net.cone_tri_face(i, j, k)
            elif net.tri_is_face(i, k, j):
                w = net.cone_tri_face(i, k, j)
            else:
                w = net.force_cone_tri(i, j, k)
            if w is not None:
                born.append(w)
    elif mode == "all":
        for (i, j, k) in cand_tri:
            w = net.cone_tri_face(i, j, k)
            if w is not None:
                born.append(w)
    elif mode == "one":
        for (i, j, k) in cand_tri:
            w = net.cone_tri_face(i, j, k)
            if w is not None:
                born.append(w)
                break
    elif mode == "hole":
        for vs in cand_hole:
            w = net.cone_hole(vs)
            if w is not None:
                born.append(w)
    elif mode == "edge":
        for vs in cand_hole:
            if not net.is_face_cycle(vs):
                continue
            e = adjacent_hole_edge(net, vs)
            if e is None:
                continue
            w = net.cone_edge(*e)
            if w is not None:
                born.append(w)
                break
    else:
        raise ValueError(f"unknown mode: {mode}")

    dead = net.prune(dmin)
    return born, dead

def zone(labels):
    """把「若干位点的标签」压成一个区：全为 "over" → "core"；含 ≥1 个 "over" → "sh"；
    其余（**含空列表**）→ "bg"。

    ⚠️ 空列表必须回 "bg"：`all(...)` 对空序列恒为 True，不能直接用。
    """
    if not labels:
        return "bg"
    if all(x == "over" for x in labels):
        return "core"
    if any(x == "over" for x in labels):
        return "sh"
    return "bg"

def radial_derivative(r, y):
    """中心差分（端点单侧）→ {"r": [...], "d": [...]}；`m < 2` → 空。"""
    m = len(r)
    if m < 2:
        return {"r": [], "d": []}
    d = [0.0] * m
    for i in range(m):
        if i == 0:
            den = r[1] - r[0]
            d[i] = (y[1] - y[0]) / den if den else 0.0
        elif i == m - 1:
            den = r[m - 1] - r[m - 2]
            d[i] = (y[m - 1] - y[m - 2]) / den if den else 0.0
        else:
            den = r[i + 1] - r[i - 1]
            d[i] = (y[i + 1] - y[i - 1]) / den if den else 0.0
    return {"r": list(r), "d": d}

def distortion(net, pos, tree=None, kappa=L1.KAPPA):
    """失真读数：边残差、holonomy、非边重叠对数（**读数，不是要消掉的误差**）。"""
    ids = net.ids()
    r = _radius(net, kappa)
    edges = L1.edge_list(net)
    nb = {v: set() for v in ids}
    for (u, w) in edges:
        nb[u].add(w)
        nb[w].add(u)
    res = [abs(math.dist(pos[u], pos[w]) - (r[u] + r[w])) for (u, w) in edges]
    tree = tree or aligned_tree(net, kappa=kappa)
    hol = list(tree["holonomy"].values())
    ov = 0
    for a in range(len(ids)):
        for b in range(a + 1, len(ids)):
            u, w = ids[a], ids[b]
            if w in nb[u]:
                continue
            if math.dist(pos[u], pos[w]) < r[u] + r[w]:
                ov += 1
    tree_res = [abs(math.dist(pos[u], pos[w]) - (r[u] + r[w]))
                for (u, w) in tree["tree_edges"]]
    def mx(xs):
        return max(xs) if xs else 0.0
    def mn(xs):
        return sum(xs) / len(xs) if xs else 0.0
    return {"edge_res_mean": mn(res), "edge_res_max": mx(res),
            "tree_res_max": mx(tree_res), "holonomy_mean": mn(hol),
            "holonomy_max": mx(hol), "n_holonomy": len(hol),
            "nonedge_overlaps": ov}

def export_obj(net, pos, path, kappa=L1.KAPPA):
    """导出 Wavefront OBJ：`v` = 节点位置（工件），`l` = 边。"""
    ids = net.ids()
    idx = {v: i + 1 for i, v in enumerate(ids)}
    with open(path, "w", encoding="utf-8") as f:
        f.write(f"# OpenSPUM L2 全局投影工件（{len(ids)} 节点 {net.E()} 边）\n")
        f.write("# 注意：坐标是投影工件，不是「真实几何」\n")
        for v in ids:
            p = pos[v]
            f.write(f"v {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n")
        for (u, w) in L1.edge_list(net):
            f.write(f"l {idx[u]} {idx[w]}\n")
    return path

def _psi(net):
    """重连势 Ψ = Σ(6−deg)²。Σ(6−deg) ≡ 12 是恒等式（帧不变），非约束；
    故 Ψ 只能在下界 ⌈144/V⌉ 及以上取值，取到下界即达该 V 的平台。"""
    return sum((6 - net.deg(v)) ** 2 for v in sorted(net.ids()))

def _fx_tetra_csr():
    """夹具用的 tetra CSR（规范 spec3 §4 公共布局）。"""
    return (cp.asarray([0, 3, 6, 9, 12], dtype=cp.int32),
            cp.asarray([1, 3, 2, 0, 2, 3, 1, 0, 3, 0, 1, 2], dtype=cp.int32),
            cp.asarray([3, 3, 3, 3], dtype=cp.int32))

def slots_of(sel, cand_ptr, cand_len):
    """sel 中各候选的角点槽位（cand_idx 中的下标），按 sel 顺序拼接。

    ragged range：把每个候选的 [cand_ptr[c], cand_ptr[c]+len_c) 展开成一维。
    seg = searchsorted(包含式前缀和, idx, 'right') 恰给出 idx 所属的段号。
    """
    if int(sel.size) == 0:
        return cp.zeros(0, dtype=cp.int32)
    rep = cand_len[sel].astype(cp.int64)
    total = int(rep.sum())
    if total == 0:
        return cp.zeros(0, dtype=cp.int32)
    idx = cp.arange(total, dtype=cp.int64)
    cum = cp.cumsum(rep)
    seg = cp.searchsorted(cum, idx, side="right")
    base = cum - rep
    return (cand_ptr[sel].astype(cp.int64)[seg] + (idx - base[seg])).astype(cp.int32)

def link_type(net, v):
    """元胞 v 的 link（N(v) 的诱导子图）类型：cycle / path / chord / disc。

    注：旋转系统在「面意义」上保证 link 恒为一个环；这里的诱导子图判据是
    更严的量：
      cycle = 干净内部元胞（诱导子图恰为一个环）
      path  = 边界元胞（诱导子图为一条未被弦闭合的路径）
      chord = N(v) 内部有多余弦 => v 处存在分离三角（面已被两侧占满）
      disc  = N(v) 诱导子图不连通 => 真正的非流形（领结/交叉）
    """
    nb = sorted(net.rot[v])
    d = len(nb)
    if d == 0:
        return "disc"
    ld = {x: 0 for x in nb}
    la = {x: [] for x in nb}
    le = 0
    for ai in range(d):
        for bi in range(ai + 1, d):
            x, y = nb[ai], nb[bi]
            if y in net.rot[x]:
                le += 1
                ld[x] += 1
                ld[y] += 1
                la[x].append(y)
                la[y].append(x)
    seen = {nb[0]}
    st = [nb[0]]
    while st:
        u = st.pop()
        for w in la[u]:
            if w not in seen:
                seen.add(w)
                st.append(w)
    if len(seen) != d:
        return "disc"
    degs = sorted(ld.values())
    if le == d and all(x == 2 for x in degs):
        return "cycle"
    if le == d - 1 and degs.count(1) == 2 and all(x in (1, 2) for x in degs):
        return "path"
    return "chord"

def _annihilation_plan(core):
    """§3.2 湮灭规划分派：(plan, budget)。

    frame_gpu 与写操作核验共用同一函数，避免「GPU 路径」与「核验路径」各自分派而漂移。
    dense（§7.4 采纳）：断两端皆负曲率的过密边；conserved 下再把 len(plan) 当创生预算。
    """
    if core.vminus == "dense":
        plan = core._plan_dense_breaks(core.net)
        return plan, (len(plan) if core.pairing == "conserved" else None)
    if core.pairing == "conserved":
        plan = core._plan_breaks(core.net)
        return plan, len(plan)
    return (), None

def project(net, kappa=KAPPA):
    """从 id + 环序一次性产出全部 L1 局部量（无求解、无迭代、无坐标）。"""
    ids = net.ids()
    ad = angle_defect(net, kappa)
    gs = grad_sigma(net)
    nodes = {}
    for v in ids:
        dv = net.deg(v)
        nodes[v] = {"deg": dv, "r": radius_of(dv, kappa), "sigma": sigma_of(dv),
                    "grad_sigma": gs.get(v), "defect": ad["defect"][v],
                    "n_incident_tri": ad["ntri"][v]}
    edges = edge_list(net)
    V, E = len(ids), len(edges)
    return {"nodes": nodes, "edges": edges, "V": V, "E": E,
            "sigma_global": (V / E) if E else float("inf"),
            "viol": ad["viol"], "nf": ad["nf"], "nh": ad["nh"],
            "def_sum": ad["def_sum"], "defect_complete": ad["nh"] == 0,
            "crystallites": crystallites(net)}

def adjacent_hole_edge(net, vs):
    """洞 vs 上第一条两端 deg>=2 的边 (i,j)（确定性）。"""
    k = len(vs)
    for t in range(k):
        i, j = vs[t], vs[(t + 1) % k]
        if net.deg(i) >= 2 and net.deg(j) >= 2:
            return (i, j)
    return None

def radial_bins(net, pos, center=None, nbins=8, kappa=L1.KAPPA):
    """径向上按「到原点的距离」分箱、取箱内均值 → {"center","center_id","r","n","sigma","deg"}。

    `center=None` → 质心；否则取该**节点 id** 的 `pos` 作原点。空箱剔除；
    `r_max − r_min < 1e-12`（等度球壳，如 icosa t=0）→ **单箱退化**。
    """
    ids = net.ids()
    if not ids:
        return {"center": None, "center_id": None, "r": [], "n": [], "sigma": [], "deg": []}
    # --- S1 原点与距离 ---
    if center is None:
        c = tuple(sum(pos[v][k] for v in ids) / len(ids) for k in range(3))
    else:
        c = pos[center]
    dist = {v: math.dist(pos[v], c) for v in ids}
    sg = {v: L1.sigma_of(net.deg(v)) for v in ids}
    # --- S2 单箱退化 ---
    rmin = min(dist.values())
    rmax = max(dist.values())
    if rmax - rmin < 1e-12:
        return {"center": c, "center_id": center, "r": [rmin], "n": [len(ids)],
                "sigma": [sum(sg[v] for v in ids) / len(ids)],
                "deg": [sum(net.deg(v) for v in ids) / len(ids)]}
    # --- S3 等宽分箱（最后一箱闭区间，防浮点漏项）---
    h = (rmax - rmin) / nbins
    buckets = [[] for _ in range(nbins)]
    for v in ids:
        i = min(nbins - 1, int((dist[v] - rmin) / h))
        buckets[i].append(v)
    # --- S4 箱内均值（只留非空箱；`r` 取箱内实际距离均值，不用箱中点）---
    out = {"center": c, "center_id": center, "r": [], "n": [], "sigma": [], "deg": []}
    for b in buckets:
        if not b:
            continue
        out["r"].append(sum(dist[v] for v in b) / len(b))
        out["n"].append(len(b))
        out["sigma"].append(sum(sg[v] for v in b) / len(b))
        out["deg"].append(sum(net.deg(v) for v in b) / len(b))
    return out

def grad_sigma(net):
    """∇σ 的局部化：分量 = mean_{w∈rot[v]}(σ_w) − σ_v。纯局部。"""
    ids = net.ids()
    sg = {v: sigma_of(net.deg(v)) for v in ids}
    out = {}
    for v in ids:
        nb = net.rot[v]
        if not nb:
            continue
        out[v] = sum(sg[w] for w in nb) / len(nb) - sg[v]
    return out

def survivors(passes, rank):
    """通过交集的候选，按 rank 升序（= CPU commit 的提交顺序）。返回 sel [m] int32。"""
    sel = cp.where(passes)[0].astype(cp.int32)
    if int(sel.size) == 0:
        return sel
    return sel[cp.argsort(rank[sel])].astype(cp.int32)

def delta(net, k=2):
    """GT-005 悬挂端密度 δ_k = |{v : deg(v) < k}| / |V|。

    注册定义取 `k=2`（公理下限）；`k=dmin` 为修剪边界读数，`k=KAPPA`（=6）为
    三角剖分的正角亏端读数。空图返回 `None`。
    """
    ids = net.ids()
    if not ids:
        return None
    return sum(1 for v in ids if net.deg(v) < k) / len(ids)

def rot_from_uv(u, v):
    """最小旋转把单位向量 u 转到单位向量 v（Rodrigues，行主序 3x3）。"""
    k = _cross(u, v)
    s = _norm(k)
    c = _dot(u, v)
    if s < 1e-12:
        if c > 0:
            return I3
        a = (1.0, 0.0, 0.0) if abs(u[0]) < 0.9 else (0.0, 1.0, 0.0)
        ax = _cross(u, a)
        n = _norm(ax)
        ax = tuple(x / n for x in ax)
        return tuple(tuple(2 * ax[i] * ax[j] - (1.0 if i == j else 0.0)
                           for j in range(3)) for i in range(3))
    kx = ((0.0, -k[2], k[1]), (k[2], 0.0, -k[0]), (-k[1], k[0], 0.0))
    kk = tuple(tuple(sum(kx[i][t] * kx[t][j] for t in range(3))
                     for j in range(3)) for i in range(3))
    f = (1.0 - c) / (s * s)
    return tuple(tuple((1.0 if i == j else 0.0) + kx[i][j] + kk[i][j] * f
                       for j in range(3)) for i in range(3))

def _cpu_keys(core, cap, drive):
    """CPU 版的候选多重集：[(type, key), ...]（type: 0 创生 / 1 湮灭）。"""
    out = []
    for c in core.propose():
        t = 0 if c["type"] == CREATION else 1
        out.append((t, c["key"]))
    return sorted(out)

def partition(net, kappa=KAPPA):
    """按度数三分区。返回 `{v: label}`，label ∈ {"over","flat","under"}。

    `deg > κ` → "over"（过密 / 负曲率端）；`deg == κ` → "flat"；`deg < κ` → "under"。
    空图返回 `{}`。
    """
    out = {}
    for v in net.ids():
        d = net.deg(v)
        out[v] = "over" if d > kappa else ("flat" if d == kappa else "under")
    return out

def rotation_from_faces(faces):
    """faces: 有向三角面 [(x,y,z), ...]（面按 x->y->z->x 定向）。

    succ[(x,y)] = z  <=>  dart (x,y) 所在面后继 dart 是 (y,z)。
    返回 rot[v] = v 的环序邻居表，满足 succ_v(w) = succ[(v,w)]。
    """
    succ = {}
    for (x, y, z) in faces:
        for (a, b, c) in ((x, y, z), (y, z, x), (z, x, y)):
            old = succ.get((a, b))
            if old is not None and old != c:
                raise ValueError(
                    f"面表定向不一致: dart ({a},{b}) 后继 {old} vs {c}")
            succ[(a, b)] = c

    verts = sorted({a for (a, _) in succ})
    rot = {}
    for v in verts:
        outs = sorted(b for (a, b) in succ if a == v)
        if not outs:
            rot[v] = []
            continue
        w0 = outs[0]
        cyc = [w0]
        w = w0
        while True:
            w = succ.get((v, w))
            if w is None:
                raise ValueError(f"顶点 {v} 的环序不闭合（不是合法旋转系统）")
            if w == w0:
                break
            cyc.append(w)
        rot[v] = cyc
    return rot

def observe(core, nframes, kappa=KAPPA, cap=None):
    """L4 入口：跑 L0 取帧序列，一次产出五组读数（**只调用 `core.frame()`**）。"""
    if cap is None:
        cap = getattr(core, "cap", None)
    dmin = getattr(core, "dmin", 3)
    nets, events = [snap(core.net)], []
    for _ in range(int(nframes)):
        events.append(dict(core.frame()))
        nets.append(snap(core.net))
    accounts = event_account(nets, kappa, cap)
    return {"accounts": accounts, "profile": annihilation_profile(accounts),
            "concentration": concentration_series(nets, cap),
            "imperfection": imperfection_series(nets, events, dmin),
            "closure": closure_series(nets),
            "V": [n.V() for n in nets], "E": [n.E() for n in nets],
            "nets": nets, "events": events}

def relax(net, pos, iters=60, w_rep=0.5, nonedge=True, center=True,
          kappa=L1.KAPPA):
    """工件精修：位置约束投影（Gauss-Seidel），确定性、无步长参数。

    ① 边：距离约束 `|p_u−p_w| = r_u + r_w`，两端各移一半；
    ② 非边：`|p_u−p_w| < r_u + r_w` 时各移一半推开（`w_rep` 权重）；
    ③ 每轮质心归零（抑制整体漂移）。
    这只是**把工件压实得更像样**，不改变「不可精确嵌入」的性质。

    ⚠️ **初始化依赖（分岔 N7）**：PBD 只降到**最近的**局部极小，残差只是上界，
    **不能**当作「不可嵌入」的证据——实测同一张 t=1 的图，换 `root` 就能命中
    精确解（边残差 3.6e-15）或陷局部极小（残差 1.24、非边重叠）。
    """
    ids = net.ids()
    if not ids:
        return {}
    r = _radius(net, kappa)
    edges = L1.edge_list(net)
    p = {v: tuple(pos[v]) for v in ids}
    nb = {v: set() for v in ids}
    for (u, w) in edges:
        nb[u].add(w)
        nb[w].add(u)
    others = ([(u, w) for u in ids for w in ids if w > u and w not in nb[u]]
              if nonedge else [])
    for _ in range(iters):
        for (u, w) in edges:
            d = tuple(p[w][k] - p[u][k] for k in range(3))
            L = _norm(d) or 1e-9
            c = 0.5 * (L - (r[u] + r[w])) / L
            p[u] = tuple(p[u][k] + c * d[k] for k in range(3))
            p[w] = tuple(p[w][k] - c * d[k] for k in range(3))
        for (u, w) in others:
            d = tuple(p[w][k] - p[u][k] for k in range(3))
            L = _norm(d) or 1e-9
            tgt = r[u] + r[w]
            if L < tgt:
                c = 0.5 * w_rep * (tgt - L) / L
                p[u] = tuple(p[u][k] - c * d[k] for k in range(3))
                p[w] = tuple(p[w][k] + c * d[k] for k in range(3))
        if center:
            cen = tuple(sum(p[v][k] for v in ids) / len(ids) for k in range(3))
            p = {v: tuple(p[v][k] - cen[k] for k in range(3)) for v in ids}
    return p

def _gpu_keys(g):
    """GPU 版的候选多重集，键的构造与 CPU 完全同形。"""
    out = []
    n_cand = int(g["key3"].shape[0])
    if n_cand:
        k1 = cp.asnumpy(g["key1"]).tolist()
        k2 = cp.asnumpy(g["key2"]).tolist()
        k3 = cp.asnumpy(g["key3"])
        for i in range(n_cand):
            row = tuple(int(x) for x in k3[i] if x >= 0)
            out.append((int(k1[i]), (int(k1[i]), int(k2[i]), row)))
    n_node = int(g["node_pos"].size)
    if n_node:
        ids = cp.asnumpy(g["ids"]).tolist()
        pos = cp.asnumpy(g["node_pos"]).tolist()
        nk2 = cp.asnumpy(g["node_key2"]).tolist()
        for i in range(n_node):
            v = int(ids[pos[i]])
            out.append((1, (1, int(nk2[i]), (v,))))
    return sorted(out)

def closure_series(rows, theta_delta=THETA_DELTA, theta_mu=THETA_MU,
                   k=K_CLOSED, key_delta="delta_kappa", key_mu="dmu"):
    """双层判据：`闭合(τ) = (δ(τ) < θ_δ) ∧ (Δμ(τ) < θ_μ)`，并统计**连续 k 帧**的段。

    N013 修正：单靠 δ 不能判闭合（δ 对锚点漂移无感）⇒ 必须两项同时成立。
    第 0 帧无 Δμ ⇒ 恒记 `False`。
    """
    flags = []
    for r in rows:
        d, mu = r.get(key_delta), r.get(key_mu)
        flags.append(bool(d is not None and mu is not None
                          and d < theta_delta and mu < theta_mu))
    segs, s = [], None
    for i, f in enumerate(flags):
        if f and s is None:
            s = i
        elif not f and s is not None:
            segs.append((s, i - 1))
            s = None
    if s is not None:
        segs.append((s, len(flags) - 1))
    long_segs = [(a, b) for (a, b) in segs if b - a + 1 >= k]
    return {"flags": flags, "segments": segs, "long_segments": long_segs,
            "closed": bool(long_segs), "k": k,
            "theta_delta": theta_delta, "theta_mu": theta_mu}

def anchor_drift(prev, cur):
    """GT-006 锚点漂移率 Δμ(τ) = (1/C)·Σ_c |μ_c(τ) − μ_c(τ−1)|。

    μ_c = 类别 c 的**度质心**（GT-006 的一维口径；本层锚点类别 = 单点 ⇒ μ_c = deg(c)），
    类别按 **id 对齐**。`churn` = 锚点集 Jaccard 距离（锚点被重新定义/诞生/消失的度量）。

    ⚠️ 无共同锚点时 `Δμ ≡ 0` —— 此时必须看 `churn`（=1.0 表示锚点集完全换血），
    不可据 `Δμ=0` 判"稳定"。
    """
    A = set(anchors_of(prev)["sinks"]) | set(anchors_of(prev)["sources"])
    B = set(anchors_of(cur)["sinks"]) | set(anchors_of(cur)["sources"])
    common, union = A & B, A | B
    churn = 0.0 if not union else 1.0 - len(common) / len(union)
    if not common:
        return {"dmu": 0.0, "churn": churn, "n_prev": len(A),
                "n_cur": len(B), "n_common": 0}
    dmu = sum(abs(cur.deg(c) - prev.deg(c)) for c in sorted(common)) / len(common)
    return {"dmu": dmu, "churn": churn, "n_prev": len(A),
            "n_cur": len(B), "n_common": len(common)}
